import net.neoforged.neoforge.fluids.FluidInteractionRegistry;
import net.neoforged.neoforge.fluids.FluidInteraction;

// Register fluid interaction
FluidInteractionRegistry.registerFluidInteraction(
    Registries.FLUID,
    Registries.BLOCK,
    (fluid, state, blockState) -> {
        // Return interaction result
        return new FluidInteraction.Result(
            Interactions.PLACE,
            new FluidStack(MY_FLUID, 1000)
        );
    }
);
